64	void SpoolMenu::open(wxWindow* owner, const ShellTheme& theme, bool dark, Host host, HeaderButton& anchor)
65	{
66	    auto self = std::make_shared<SpoolMenu>(owner, theme, dark, std::move(host));
67	    self->m_anchor = &anchor;
68	    self->m_menu = new HeaderMenu(owner, theme, dark, {});
69	    show_spools(self);
70	    self->m_menu->open(anchor);
71	    // No dismiss listener: the row callbacks own the controller, so it is
72	    // released when the popup's rows are destroyed and any queued callback has
73	    // run -- never while one is still pending.
74	}
