99	void SpoolMenu::show_spools(const Ptr& self)
100	{
101	    auto* menu = self->m_menu.get();
102	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
103	    menu->set_header_builder(nullptr);
104	    const auto printer = SetupCommands::current_printer();
105	    const auto current = self->m_host.store->current(printer.preset_name,
106	                                               SetupCommands::current_filament().preset_name,
107	                                               SetupCommands::current_colour().ToStdString());
108	
109	    std::vector<HeaderMenuItem> rows;
110	    rows.push_back(title_row(wxString::Format(_L("SPOOLS ON %s"), printer.nickname.Upper())));
111	
112	    // Never truncated and never scrolled: a person keeps three to fifteen
113	    // spools, and the whole design rests on the right one being one click away.
114	    for (const Workspace::Spool& spool : self->m_host.store->spools_for(printer.preset_name)) {
115	        HeaderMenuItem row;
116	        row.label            = spool_label(spool);
117	        row.decoration.dot   = wxColour(wxString::FromUTF8(spool.colour));
118	        row.decoration.check = current.has_value() && current->id == spool.id;
119	        row.invoke           = [self, spool] { SpoolMenu::select(self, spool); };
120	        row.row_action       = HeaderIcon::More;
121	        row.invoke_row_action = [self, spool] { show_row_menu(self, spool); };
122	        rows.push_back(std::move(row));
123	    }
124	
125	    HeaderMenuItem other;
126	    other.separator          = true;
127	    other.label              = _L("Other spool…");
128	    other.decoration.trailing = HeaderIcon::Right;
129	    other.keeps_open         = true;
130	    other.invoke             = [self] { show_other_spool(self); };
131	    rows.push_back(std::move(other));
132	
133	    menu->replace_items(std::move(rows));
134	}
