223	void SpoolMenu::show_other_spool(const Ptr& self)
224	{
225	    auto* menu = self->m_menu.get();
226	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
227	    const auto printer = SetupCommands::current_printer();
228	
229	    // The search field lives above the rows and keeps focus while the result
230	    // list rebuilds under it on every keystroke.
231	    menu->set_header_builder([self](wxWindow* parent) -> wxWindow* {
232	        const auto& palette = self->m_theme.palette(self->m_dark);
233	        auto* field = new wxTextCtrl(parent, wxID_ANY, self->m_search, wxDefaultPosition, wxDefaultSize, wxTE_PROCESS_ENTER);
234	        field->SetHint(_L("Search filaments"));
235	        field->SetFont(Label::Body_14);
236	        field->SetBackgroundColour(palette.surface_subtle);
237	        field->SetForegroundColour(palette.text_primary);
238	        field->SetMinSize(wxSize(-1, field->FromDIP(28)));
239	        field->Bind(wxEVT_TEXT, [self](wxCommandEvent& event) {
240	            self->m_search = event.GetString();
241	            // Rebuilding destroys this control, so leave the current event
242	            // first and let the rebuild re-create the field with the text.
243	            // The popup owns the deferral: if it dismisses in between, the
244	            // weak reference drops the call and this controller is gone too.
245	            self->m_owner->CallAfter([self, alive = wxWeakRef<wxWindow>(self->m_menu)] {
246	                if (alive) show_other_spool(self);
247	            });
248	        });
249	        self->m_search_field = field;
250	        return field;
251	    }, 1); // below the back row, as the design places it
252	
253	    std::vector<HeaderMenuItem> rows;
254	    // The title is also the way back to the spool list; without it the only
255	    // exit from this step is dismissing the whole menu.
256	    HeaderMenuItem back;
257	    back.label      = wxString::Format(_L("OTHER SPOOL · FITS %s · %g MM"), printer.nickname.Upper(), printer.nozzle);
258	    back.icon       = HeaderIcon::Back;
259	    back.keeps_open = true;
260	    back.invoke     = [self] { self->m_search.clear(); show_spools(self); };
261	    rows.push_back(std::move(back));
262	
263	    for (const auto& filament : SetupCommands::compatible_filaments()) {
264	        if (!matches(filament, self->m_search)) continue;
265	        HeaderMenuItem row;
266	        row.label = filament.vendor.empty() ? filament.alias : filament.alias + middot() + filament.vendor;
267	        // A dashed ring: this preset is not a spool yet, and has no colour.
268	        row.decoration.dot = wxColour();
269	        row.keeps_open     = true;
270	        row.invoke         = [self, filament] { show_new_spool(self, filament); };
271	        rows.push_back(std::move(row));
272	    }
273	
274	    HeaderMenuItem generic;
275	    generic.separator = true;
276	    generic.label     = _L("Generic preset…");
277	    generic.keeps_open = true;
278	    generic.invoke    = [self] {
279	        // Generic presets are ordinary compatible presets from the "Generic"
280	        // vendor, so this is the same list filtered, not a separate source.
281	        self->m_search = "Generic";
282	        show_other_spool(self);
283	    };
284	    rows.push_back(std::move(generic));
285	
286	    HeaderMenuItem import;
287	    import.label  = _L("Import a preset file…");
288	    import.invoke = [] { SetupCommands::import_preset_file(); };
289	    rows.push_back(std::move(import));
290	
291	    menu->replace_items(std::move(rows));
292	    // The rebuild replaced the field, so focus and caret have to be restored
293	    // or every keystroke would land at the start of what was already typed.
294	    if (self->m_search_field) {
295	        self->m_search_field->SetFocus();
296	        self->m_search_field->SetInsertionPointEnd();
297	    }
298	}
