300	void SpoolMenu::show_new_spool(const Ptr& self, const SetupCommands::FilamentInfo& preset)
301	{
302	    auto* menu = self->m_menu.get();
303	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
304	    const auto printer = SetupCommands::current_printer();
305	    const bool first   = self->m_new_preset != preset.preset_name;
306	    if (first) {
307	        self->m_new_preset      = preset.preset_name;
308	        self->m_new_material    = preset.material.empty() ? preset.alias : preset.material;
309	        self->m_new_vendor      = preset.vendor;
310	        self->m_new_colour      = wxColour(wxString::FromUTF8(SetupCommands::swatches().front().hex));
311	        self->m_new_name_edited = false;
312	    }
313	    if (!self->m_new_name_edited) {
314	        const wxString word = SetupCommands::colour_word(self->m_new_colour);
315	        self->m_new_name = word.empty() ? preset.alias : word + " " + self->m_new_material;
316	    }
317	
318	    menu->set_header_builder([self, preset](wxWindow* parent) -> wxWindow* {
319	        const auto& palette = self->m_theme.palette(self->m_dark);
320	        auto* panel = new wxPanel(parent);
321	        panel->SetBackgroundColour(palette.surface_raised);
322	        auto* column = new wxBoxSizer(wxVERTICAL);
323	
324	        auto caption = [&](const wxString& text, const wxFont& font, const wxColour& colour) {
325	            auto* label = new wxStaticText(panel, wxID_ANY, text);
326	            label->SetFont(font);
327	            label->SetForegroundColour(colour);
328	            return label;
329	        };
330	        column->Add(caption(preset.alias, Label::Body_14, palette.text_primary), 0, wxBOTTOM, panel->FromDIP(8));
331	        column->Add(caption(_L("COLOUR"), Label::Body_10, palette.text_secondary), 0, wxBOTTOM, panel->FromDIP(4));
332	
333	        // Twelve swatches on two rows. Each is a small owner-drawn panel
334	        // rather than a button: it carries one value and one selected ring.
335	        auto* grid = new wxGridSizer(kSwatchesPerRow, panel->FromDIP(4), panel->FromDIP(4));
336	        for (const auto& swatch : SetupCommands::swatches()) {
337	            const wxColour colour(wxString::FromUTF8(swatch.hex));
338	            auto* cell = new wxPanel(panel, wxID_ANY, wxDefaultPosition, panel->FromDIP(wxSize(24, 24)));
339	            cell->SetName(swatch.name);
340	            cell->SetToolTip(_(swatch.name));
341	            cell->SetBackgroundStyle(wxBG_STYLE_PAINT);
342	            cell->Bind(wxEVT_PAINT, [self, cell, colour, palette](wxPaintEvent&) {
343	                wxPaintDC dc(cell);
344	                dc.SetBackground(wxBrush(palette.surface_raised));
345	                dc.Clear();
346	                const bool chosen = self->m_new_colour == colour;
347	                dc.SetBrush(wxBrush(colour));
348	                dc.SetPen(wxPen(chosen ? palette.border_strong : palette.border_subtle, chosen ? 2 : 1));
349	                const wxRect box = cell->GetClientRect().Deflate(chosen ? 1 : 2);
350	                dc.DrawRoundedRectangle(box, cell->FromDIP(6)); // standard control radius
351	            });
352	            cell->Bind(wxEVT_LEFT_UP, [self, colour, preset](wxMouseEvent&) {
353	                self->m_new_colour = colour;
354	                self->m_owner->CallAfter([self, preset, alive = wxWeakRef<wxWindow>(self->m_menu)] {
355	                    if (alive) show_new_spool(self, preset);
356	                });
357	            });
358	            grid->Add(cell, 0);
359	        }
360	        column->Add(grid, 0, wxBOTTOM, panel->FromDIP(8));
361	
362	        auto* name = new wxTextCtrl(panel, wxID_ANY, self->m_new_name);
363	        name->SetFont(Label::Body_14);
364	        name->SetBackgroundColour(palette.surface_subtle);
365	        name->SetForegroundColour(palette.text_primary);
366	        name->SetMinSize(wxSize(-1, panel->FromDIP(28)));
367	        name->Bind(wxEVT_TEXT, [self](wxCommandEvent& event) {
368	            // Once the person types, the colour no longer rewrites the name.
369	            self->m_new_name        = event.GetString();
370	            self->m_new_name_edited = true;
371	        });
372	        self->m_name_field = name;
373	        column->Add(name, 0, wxEXPAND);
374	
375	        panel->SetSizerAndFit(column);
376	        return panel;
377	    }, 1); // below the back row
378	
379	    std::vector<HeaderMenuItem> rows;
380	    HeaderMenuItem back;
381	    back.label      = wxString::Format(_L("NEW SPOOL FOR %s"), printer.nickname.Upper());
382	    back.icon       = HeaderIcon::Back;
383	    back.keeps_open = true;
384	    back.invoke     = [self] { self->m_new_preset.clear(); show_other_spool(self); };
385	    rows.push_back(std::move(back));
386	
387	    HeaderMenuItem use;
388	    use.label                = _L("Use this spool");
389	    use.separator            = true;
390	    use.decoration.detail    = _L("adds it to the list");
391	    use.decoration.bold      = true;
392	    use.invoke               = [self, printer] {
393	        Workspace::Spool spool;
394	        spool.printer_preset  = printer.preset_name;
395	        spool.filament_preset = self->m_new_preset;
396	        spool.colour          = self->m_new_colour.GetAsString(wxC2S_HTML_SYNTAX).ToStdString();
397	        spool.name            = self->m_new_name.Trim().ToStdString();
398	        spool.brand           = self->m_new_vendor.ToStdString();
399	        if (spool.name.empty()) spool.name = self->m_new_material.ToStdString();
400	        SpoolMenu::select(self, self->m_host.store->add(std::move(spool)));
401	    };
402	    rows.push_back(std::move(use));
403	
404	    menu->replace_items(std::move(rows));
405	    if (self->m_name_field && !self->m_new_name_edited) self->m_name_field->SetInsertionPointEnd();
406	}
